---@param player SBasePlayer | CBasePlayer
function BattleInfo:initListener(player)
    if isClient then
        self:addKeyObserver(Define.BattleInfoKey.PlayerAction, function(_, _, value)
            local isEmpty = value == ""
            if isEmpty then
                player:setBaseAction(nil)
                player:setUpperAction(nil)
            else
                player:setBaseAction(value)
                player:setUpperAction(value)
            end
            if player.Player then
                player.Player:setBaseAction(isEmpty and 1 or 1000)
                player.Player:setUpperAction(isEmpty and 1 or 1000)
                player.Player:setBoolProperty("DisableUpdateAnimState", not isEmpty)
            end
        end)
    else
        self:addKeyObserver(Define.BattleInfoKey.DamageImmunity, function(_, _, value)
            if value > 0 then
                player:addCustomEffect("DamageImmunity", "g1048_ares_shield_skill.effect", -1, 1)
            else
                player:addCustomEffect("DamageImmunity", "g1048_ares_shield_skill.effect", 0, 1)
            end
        end)
    end
    ---@type table<SLivingInterface | CLivingInterface, boolean>
    self.followers = {}
end

---@param attacker SBasePlayer
function BattleInfo:setAttacker(attacker)
    if attacker then
        self:setValue(Define.BattleInfoKey.Attacker, attacker.userId)
        self:setValue(Define.BattleInfoKey.AttackerTime, os.time())
    else
        self:setValue(Define.BattleInfoKey.Attacker, 0)
        self:setValue(Define.BattleInfoKey.AttackerTime, 0)
    end
end

---@return SBasePlayer
function BattleInfo:getAttacker()
    if os.time() - self:getValue(Define.BattleInfoKey.AttackerTime) <= 8 then
        local userId = self:getValue(Define.BattleInfoKey.Attacker)
        return PlayerManager:getPlayerByUserId(userId)
    else
        return nil
    end
end

function BattleInfo:canHurt()
    local time = tonumber(HostApi.curTimeString())
    local hurt = self:getValue(Define.BattleInfoKey.HurtTime)
    return time - hurt >= 350
end

function BattleInfo:onHurt()
    self:setValue(Define.BattleInfoKey.HurtTime, tonumber(HostApi.curTimeString()))
end

function BattleInfo:onAttack(cdTime)
    cdTime = cdTime or 300
    local time = tonumber(HostApi.curTimeString()) + cdTime
    self:setValue(Define.BattleInfoKey.AttackTime, time)
end

function BattleInfo:canAttack()
    local time = tonumber(HostApi.curTimeString())
    local attack = self:getValue(Define.BattleInfoKey.AttackTime)
    return attack < time
end

---@param dead SBasePlayer
---@param killer SBasePlayer
function BattleInfo:onDead(dead, killer, source)
    local diePos = dead:getPosition()
    self:setValue(Define.BattleInfoKey.DeadPosition, diePos)
    if dead.info:checkLoginDays(1) then
        if dead.info:getValue(Define.PlayerInfoKey.InHome) then
            diePos = dead.home:toSavePos(VectorUtil.toVector3i(diePos))
        else
            diePos = VectorUtil.toVector3i(diePos)
        end
        ReportEvent.reportEvent(dead.userId, "newplayer_die", false, {
            item_id = dead:getPlayerInventory():getHandItemId(),
            source = source,
            task_group = dead.guide_task.curGuideKey,
            position = VectorUtil.hashVector3(diePos),
        })
    end
    if killer then
        killer.battle:incValue(Define.BattleInfoKey.MultipleKill, 1)
        local kills = math.min(5, killer.battle:getValue(Define.BattleInfoKey.MultipleKill))
        local killerId = killer.battle:getValue(Define.BattleInfoKey.Killer)
        if killerId == dead.userId then
            MsgSender.sendTopTips(3, "battle.tip.revenge" .. kills, killer.name, dead.name)
        else
            MsgSender.sendTopTips(3, "battle.tip.kill" .. kills, killer.name, dead.name)
        end
        self:setValue(Define.BattleInfoKey.Killer, killer.userId)
        killer.battle:incValue(Define.BattleInfoKey.PVPKill, 1)
        killer.battle:incValue(Define.BattleInfoKey.PVPKillTotal, 1)
    else
        MsgSender.sendTopTips(3, "battle.tip.accident", dead.name)
    end
    self:setValue(Define.BattleInfoKey.MultipleKill, 0)
end

function BattleInfo:onDamageMonster(gid, damage)
    local key = "monster_damage:" .. gid
    local value = self:getValue(key)
    if not value then
        return
    end
    value = value + damage
    self:setValue(key, value)
end

function BattleInfo:clearMonsterDamage(gid)
    local key = "monster_damage:" .. gid
    local value = self:getValue(key)
    if not value then
        return
    end
    self:setValue(key, 0)
end

---判断是否处于中毒状态
function BattleInfo:inPoison()
    return self:getValue(Define.BattleInfoKey.PoisonCount) > 0
end

---是否处于观战状态
function BattleInfo:isInWatchBattle()
    return self:getValue(Define.BattleInfoKey.PkWatchBattle)
end

---判断是否是队友
---@param target SBasePlayer
function BattleInfo:isBattleTeammate(target)
    if self == target.battle then
        return true
    end
    local battleId = self:getValue(Define.BattleInfoKey.PkBattleId)
    if battleId == 0 or battleId ~= target.battle:getValue(Define.BattleInfoKey.PkBattleId) then
        ---在不同的Pk战场
        return false
    end
    local team1 = self:getValue(Define.BattleInfoKey.PkBattleTeam)
    local team2 = target.battle:getValue(Define.BattleInfoKey.PkBattleTeam)
    return team1 == team2
end

---判断是否可以攻击目标
---@param target SBasePlayer 目标
function BattleInfo:isCanAttackTarget(target)
    if self == target.battle then
        return false
    end
    if self:isInWatchBattle() or target.battle:isInWatchBattle() then
        return false
    end
    local respawn = self:getValue(Define.BattleInfoKey.RespawnWaitTime)
    if respawn > os.time() then
        ---等待复活中，不能对人造成伤害
        return false
    end
    if target.battle:inPkBattle() then
        return self:canPkBattleAttack(target)
    else
        return not target.battle:getValue(Define.BattleInfoKey.InSafeArea)
    end
end

---检测是否在相同的PK战场中可以伤害目标
---@param target SBasePlayer 目标
function BattleInfo:canPkBattleAttack(target)
    if not self:getValue(Define.BattleInfoKey.PkStarting) then
        ---Pk未开始
        return not target.battle:getValue(Define.BattleInfoKey.InSafeArea)
    end
    local battleId = self:getValue(Define.BattleInfoKey.PkBattleId)
    if battleId ~= target.battle:getValue(Define.BattleInfoKey.PkBattleId) then
        ---在不同的Pk战场
        return false
    end
    local team1 = self:getValue(Define.BattleInfoKey.PkBattleTeam)
    local team2 = target.battle:getValue(Define.BattleInfoKey.PkBattleTeam)
    if team1 == team2 then
        ---在相同的队伍
        return false
    end
    local battle = PkBattleFieldMgr:get(battleId)
    if battle and battle:isUseSafeArea() then
        return not target.battle:getValue(Define.BattleInfoKey.InSafeArea)
    else
        return true
    end
end

function BattleInfo:inPkBattle(class)
    local battleId = self:getValue(Define.BattleInfoKey.PkBattleId)
    if battleId == 0 then
        return false
    end
    if class then
        local battle = PkBattleFieldMgr:get(battleId)
        if battle and (battle.cfg.Class or battle.name) == class then
            return true
        else
            return false
        end
    else
        return true
    end
end

function BattleInfo:canPkBattle()
    return self:getValue(Define.BattleInfoKey.PkCooldownTime) < os.time()
end

function BattleInfo:getSoloWin()
    return self:getValue(Define.BattleInfoKey.SoloStreakWin)
            .. "/" .. self:getValue(Define.BattleInfoKey.SoloMaxStreakWin)
            .. "/" .. self:getValue(Define.BattleInfoKey.SoloTotalWin)
end

function BattleInfo:isInvincible()
    return self:getValue(Define.BattleInfoKey.InvincibleTime) >= os.time()
end

---@param player SBasePlayer
function BattleInfo:setInvincible(player, second)
    local time1 = self:getValue(Define.BattleInfoKey.InvincibleTime)
    local time2 = os.time() + second
    if time1 < time2 then
        self:setValue(Define.BattleInfoKey.InvincibleTime, time2)
        player:addCustomEffect("Invincible", "130_wudi.effect", second * 1000, 1)
    end
end

---消耗伤害免疫次数
function BattleInfo:consumeDamageImmunity()
    local times = self:getValue(Define.BattleInfoKey.DamageImmunity)
    if times > 0 then
        self:decValue(Define.BattleInfoKey.DamageImmunity, 1)
        return true
    else
        return false
    end
end

function BattleInfo:isBanAttack()
    if self:getValue(Define.BattleInfoKey.BanAttack) then
        return true
    else
        return not self:canAttack()
    end
end

function BattleInfo:isBanMagicEffect()
    return self:getValue(Define.BattleInfoKey.BanMagicEffect) > 0
end

---@param follower SLivingInterface | CLivingInterface
function BattleInfo:onAddFollower(follower)
    self.followers[follower] = true
end

---@param follower SLivingInterface | CLivingInterface
function BattleInfo:onSubFollower(follower)
    self.followers[follower] = nil
end

---随从抵消伤害计算
---@param attacker SBasePlayer 攻击者
---@param master SBasePlayer 主人
---@param real boolean 是否是真实伤害
function BattleInfo:onFollowerCounteractDamage(attacker, master, damage, real)
    if damage <= 0 and real <= 0 then
        return 0, 0
    end
    local total1, total2 = 0, 0
    ---@type table<SLivingInterface | CLivingInterface, boolean>
    local followers = TableUtil.copyTable1(self.followers)
    ---@param follower SFollowPetInterface
    for follower, _ in pairs(followers) do
        if follower and follower.onCounteractDamage then
            local counteractRate
            local rate = follower.attr:getValue(Define.AttrInfoKey.DmgCounteractBlock)
            if math.random(1, 100) <= rate then
                master:addCustomEffect("DmgCounteractBlock", "g1048_pet_shield_skill.effect", 1000)
                counteractRate = 1
            else
                counteractRate = math.max(0, follower.attr:getValue(Define.AttrInfoKey.DmgCounteractRate) / 100)
            end
            local damage1 = damage * counteractRate
            local damage2 = real * counteractRate
            if follower:onCounteractDamage(attacker, damage1, damage2) then
                total1 = total1 + damage1
                total2 = total2 + damage2
            end
        end
    end
    if total1 > 0 then
        damage = math.max(0, damage - total1)
    end
    if total2 > 0 then
        real = math.max(0, real - total2)
    end
    return damage, real
end

---随从触发Buff
function BattleInfo:triggerFollowerBuff(name, ...)
    for follower, _ in pairs(self.followers) do
        if not follower:isDead() then
            follower.buff:trigger(name, ...)
        end
    end
end

return BattleInfo